(function($){'use strict';$(document).ready(function(){if(typeof Chart==='undefined'){return;}const defaultOptions={responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{padding:15,font:{size:12}}},tooltip:{backgroundColor:'rgba(0,0,0,0.8)',padding:12,cornerRadius:4,titleFont:{size:14,weight:'bold'},bodyFont:{size:13}}}};const colors={primary:'#737d5d',secondary:'#8b9575',accent:'#d4d8c8',success:'#28a745',warning:'#ffc107',danger:'#dc3545',info:'#17a2b8'};window.createBarChart=function(canvasId,labels,data,label,color=colors.primary){const ctx=document.getElementById(canvasId);if(!ctx)return null;return new Chart(ctx,{type:'bar',data:{labels:labels,datasets:[{label:label,data:data,backgroundColor:color,borderColor:color,borderWidth:1}]},options:{...defaultOptions,scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});};window.createLineChart=function(canvasId,labels,datasets){const ctx=document.getElementById(canvasId);if(!ctx)return null;const formattedDatasets=datasets.map((dataset,index)=>{const colorKeys=Object.keys(colors);const color=colors[colorKeys[index % colorKeys.length]];return{label:dataset.label,data:dataset.data,borderColor:color,backgroundColor:color+'20',tension:0.4,fill:true,...dataset};});return new Chart(ctx,{type:'line',data:{labels:labels,datasets:formattedDatasets},options:{...defaultOptions,scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});};window.createDoughnutChart=function(canvasId,labels,data,backgroundColors=null){const ctx=document.getElementById(canvasId);if(!ctx)return null;const bgColors=backgroundColors||[colors.primary,colors.secondary,colors.accent,colors.success,colors.warning,colors.danger,colors.info];return new Chart(ctx,{type:'doughnut',data:{labels:labels,datasets:[{data:data,backgroundColor:bgColors,borderWidth:2,borderColor:'#fff'}]},options:{...defaultOptions,cutout:'60%'}});};window.createPieChart=function(canvasId,labels,data,backgroundColors=null){const ctx=document.getElementById(canvasId);if(!ctx)return null;const bgColors=backgroundColors||[colors.primary,colors.secondary,colors.accent,colors.success,colors.warning,colors.danger,colors.info];return new Chart(ctx,{type:'pie',data:{labels:labels,datasets:[{data:data,backgroundColor:bgColors,borderWidth:2,borderColor:'#fff'}]},options:defaultOptions});};window.createHorizontalBarChart=function(canvasId,labels,data,label,color=colors.primary){const ctx=document.getElementById(canvasId);if(!ctx)return null;return new Chart(ctx,{type:'bar',data:{labels:labels,datasets:[{label:label,data:data,backgroundColor:color,borderColor:color,borderWidth:1}]},options:{...defaultOptions,indexAxis:'y',scales:{x:{beginAtZero:true,ticks:{precision:0}}}}});};window.updateChartData=function(chart,labels,data){if(!chart)return;chart.data.labels=labels;if(Array.isArray(data[0])){data.forEach((dataset,index)=>{if(chart.data.datasets[index]){chart.data.datasets[index].data=dataset;}});}else{chart.data.datasets[0].data=data;}chart.update();};window.destroyChart=function(chart){if(chart&&typeof chart.destroy==='function'){chart.destroy();}};window.malisafiChartColors=colors;});})(jQuery);